def dump(path,obj): path.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def loc(path,needle):
 lines=path.read_text().splitlines()
 return {'path':str(path),'line':next(i+1 for i,s in enumerate(lines) if needle in s),'anchor_text':needle}
def link(l,label=None): return '['+(label or l['anchor_text'])+']('+l['path']+':'+str(l['line'])+')'

