retrieved=json.loads((OUT/'evidence/retrieval-record.json').read_text())
source_rows=[]
for ident,title,url,version,files,locator,judgment in SOURCES:
 captures=[]
 for name in files:
  p=OUT/'evidence'/name
  captures.append({'path':str(p),'relative_path':'evidence/'+name,'sha256':sha(p),'bytes':p.stat().st_size})
 stamps=[x['accessed_at_utc'] for x in retrieved if any(Path(x.get('path','')).name==f for f in files)]
 row={'source_id':ident,'title':title,'primary_url':url,'version_or_commit':version,'locator':locator,'accessed_at_utc':stamps or ['2026-10-10 reviewer web access; see saved tool captures'],'observed_operation':'Independent read-only primary retrieval and semantic reading; no fetched implementation executed','governing_conditions_and_applicability':judgment,'captures':captures}
 source_rows.append(row)
 note=['# '+ident+' — '+title,'', '[Governing primary source]('+url+')','', '**Version:** '+version,'','**Locator:** '+locator,'','**Independent assessment:** '+judgment,'','**Evidence captures:**','']
 note += ['- ['+Path(x['path']).name+']('+x['relative_path'].removeprefix('evidence/')+') — SHA-256 `'+x['sha256']+'`' for x in captures]
 (OUT/'evidence'/(ident+'-review.md')).write_text('\n'.join(note)+'\n')

